"""The generated files (records_layout §6): each written from its family's records and ``_header.md``.

Every generated file begins with one marker line naming the command, then its ``_header.md`` verbatim, then its
entries. Generation is deterministic: a fixed order, and nothing but the records' own fields (no dates, SHAs, clock
or locale). Until R3's presentation commit the forms are today's (RL11): each file as it was before the migration,
rebuilt from the records and their ``legacy`` fields, so the migration can prove byte for byte that nothing is lost.

Status is derived, never stored (§4): a decision's status comes from every other record's ``supersedes``,
``amends``, ``confirms`` and ``corrects``, and its own ``amended_by_external``, ``restates`` and ``also_in``.
"""

from __future__ import annotations

import hashlib
import re
from collections import defaultdict
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from pathlib import PurePosixPath

from records import BY_NAME, HEADER, LESSON_SECTIONS, UNKNOWN, Record, id_key, load_records

# TEMPORARY(phase1/records-build): today's forms, rebuilt from the records' legacy fields, until R3's presentation
# commit switches the generator to §6's (RL11) and removes these renderers and this switch. While they hold, the prose
# duplicating a field stays in the body, and lint_records holds the two to agree.
TODAYS_FORM = True
LESSONS_FILE = "docs/lessons_maxim_in_games.md"
GAPS_FILE = "docs/known_gaps.md"
BACKLOG_FILE = "docs/standards_backlog.md"
DECISIONS_INDEX = "docs/generated/decisions_index.md"
DECISION_HEAD = "| Id | Ruling | Who, date | Owner section | Status |\n|---|---|---|---|---|\n"
BACKLOG_HEAD = "| ID | Rule it enforces | The check | Lands with |\n|---|---|---|---|\n"
INDEX_HEAD = (
    "# Decisions index\n\nEvery decision record, one line each, in id order (`docs/design/records_layout.md` §5, §6). "
    "Two branches adding decisions both change this file, so their conflict is the duplicate-id detector: resolve it "
    "with `scripts/records.py index`, never by hand.\n\n"
    "| Id | Slug | Title | Design | Status |\n|---|---|---|---|---|\n"
)
_RELATED_BY = {
    "supersedes": "superseded by",
    "amends": "amended by",
    "confirms": "confirmed by",
    "corrects": "corrected by",
}


MARKER = "<!-- Generated by `scripts/records.py index`"  # how every generated file begins: the one owner of it


def marker(source: str) -> str:
    return f"{MARKER} from {source}; edit the records there, never this file. -->\n"


_SEAL = re.compile(r" sha256:([0-9a-f]{64}) -->$")


def seal(text: str) -> str:
    """The generated text with its body's SHA-256 written into its marker line (owner's ruling on delta D1,
    2026-11-27): a file whose body still matches its seal is untouched since ``index`` wrote it."""
    first, body = text.split("\n", 1)
    digest = hashlib.sha256(body.encode("utf-8")).hexdigest()
    return f"{first.removesuffix(' -->')} sha256:{digest} -->\n{body}"


def unedited(text: str) -> bool:
    """True when a generated file's body is the one its marker line's seal names: nothing touched it since
    ``index`` wrote it, so regenerating it discards nothing."""
    first, _, body = text.partition("\n")
    m = _SEAL.search(first)
    return m is not None and first.startswith(MARKER) and m.group(1) == hashlib.sha256(body.encode("utf-8")).hexdigest()


@dataclass(frozen=True)
class Relations:
    """Who names each decision id, by relation: the later rulings that supersede, amend, confirm or correct it."""

    by: Mapping[tuple[str, str], tuple[str, ...]]  # (relation, id) -> the ids of the records that name it

    @classmethod
    def of(cls, decisions: Iterable[Record]) -> Relations:
        found: dict[tuple[str, str], list[str]] = defaultdict(list)
        for record in sorted(decisions, key=lambda r: (id_key(r.id), r.log)):
            for relation in _RELATED_BY:
                for target in record.strings(relation):
                    found[(relation, target)].append(record.id)
        return cls({k: tuple(v) for k, v in found.items()})

    def named(self, relation: str, ident: str) -> tuple[str, ...]:
        return self.by.get((relation, ident), ())


def external_name(path: str) -> str:
    """How a status names a ruling's file: ``docs/design/reviews/docs_contracts/rulings.md`` is ``docs-contracts``."""
    return PurePosixPath(path).parent.name.replace("_", "-")


def status(record: Record, log: str, relations: Relations) -> str:
    """A decision's derived status as its row in ``log`` shows it: one base, then each relation, then ``also in``."""
    superseded = relations.named("supersedes", record.id)
    restates = record.strings("restates")
    if superseded:
        parts = [f"superseded by {', '.join(superseded)}"]
    elif restates:
        parts = [f"restates {', '.join(restates)}"]
    else:
        parts = ["live"]
    parts += [f"amended by {i}" for i in relations.named("amends", record.id)]
    external = record.maps("amended_by_external")
    parts += [f"amended by {external_name(str(e['path']))} ruling {e['ruling']}" for e in external]
    parts += [f"{_RELATED_BY[r]} {i}" for r in ("confirms", "corrects") for i in relations.named(r, record.id)]
    parts += [f"also in `decisions/{other}.md`" for other in logs_of(record) if other != log]
    return "; ".join(parts)


def logs_of(record: Record) -> list[str]:
    """Every log a decision is listed in, by name: its own directory's and its ``also_in``."""
    return sorted({record.log, *record.strings("also_in")})


def _legacy_row(record: Record, log: str) -> dict[str, object]:
    """A decision's legacy row for ``log``, without its absent cells, which render from the fields."""
    rows = record.legacy.get("rows", ())
    for row in rows if isinstance(rows, tuple) else ():
        if isinstance(row, Mapping) and row["log"] == log:
            return {k: v for k, v in row.items() if v is not None}
    return {}


def decision_row(record: Record, log: str, relations: Relations) -> str:
    """A decision's row in ``log``: each cell from the fields, or from ``legacy`` where today's text differs."""
    meta, legacy = record.meta, _legacy_row(record, log)
    qualifier = f", {meta['qualifier']}" if meta["qualifier"] else ""
    when = "" if meta["date"] == UNKNOWN else f", {meta['date']}"
    cells = (
        legacy.get("id_cell", f"{record.id}{qualifier}"),
        legacy.get("ruling", record.body.rstrip("\n")),
        legacy.get("who_date", f"{meta['who']}{when}"),
        legacy.get("owner_section", meta["owner_section"]),
        legacy.get("status", status(record, log, relations)),
    )
    return "| " + " | ".join(map(str, cells)) + " |\n"


def _position(record: Record, log: str) -> tuple[int, tuple[int, str, int, str]]:
    """Where a row stands in its log: its recorded position, else after every positioned row, in id order."""
    position = _legacy_row(record, log).get("position")
    return (position if isinstance(position, int) else 10**6, id_key(record.id))


def decision_log(log: str, header: str, decisions: list[Record], relations: Relations) -> str:
    listed = [r for r in decisions if log in logs_of(r)]
    rows = "".join(decision_row(r, log, relations) for r in sorted(listed, key=lambda r: _position(r, log)))
    return marker(f"docs/design/decisions/{log}/") + header + DECISION_HEAD + rows


def decisions_index(decisions: list[Record], relations: Relations) -> str:
    rows = [
        f"| {r.id} | {r.slug} | {r.title} | `{r.log}.md` | {status(r, r.log, relations)} |\n"
        for r in sorted(decisions, key=lambda r: (id_key(r.id), r.log))
    ]
    return marker("docs/design/decisions/*/") + INDEX_HEAD + "".join(rows)


def lesson_heading(record: Record) -> str:
    tail = record.legacy.get("heading_tail") or ""
    when = "" if record.meta["date"] == UNKNOWN else f"{record.meta['date']}"
    return f"### {record.id}. {record.title} ({when}{tail})\n"


def lessons_file(header: str, lessons: list[Record]) -> str:
    """Today's form: the header, then each section's lessons in id order, each heading over its body."""
    blocks: list[str] = []
    for section in LESSON_SECTIONS:
        members = sorted((r for r in lessons if r.meta["section"] == section), key=lambda r: id_key(r.id))
        if members:
            blocks.append(f"## {section}\n")
            blocks += [lesson_heading(r) + "\n" + r.body for r in members]
    return marker("docs/lessons/") + header + "\n".join(blocks)


def _bullet(body: str) -> str:
    lines = body.rstrip("\n").split("\n")
    return "".join(("- " if i == 0 else "  ") + line + "\n" for i, line in enumerate(lines))


def gaps_file(header: str, gaps: list[Record]) -> str:
    """Today's form: the gaps in their recorded order under their group lines; gaps added later come last."""

    def place(r: Record) -> tuple[int, str]:
        position = r.legacy.get("position")
        return (position if isinstance(position, int) else 10**6, r.slug)

    out, group = [], None
    for record in sorted(gaps, key=place):
        mine = record.legacy.get("group", group)
        if mine != group and mine is not None:
            out.append(("\n" if group is not None else "") + f"{mine}\n")
            group = mine
        out.append(_bullet(record.body))
    return marker("docs/known_gaps/") + header + "".join(out)


def backlog_file(header: str, rows: list[Record]) -> str:
    """Today's form: the table in id order; a row recorded with three cells keeps three."""
    lines = []
    for r in sorted(rows, key=lambda r: id_key(r.id)):
        cells = [r.id, str(r.meta["rule"]), r.body.rstrip("\n")]
        if not r.legacy.get("three_cells"):
            cells.append(str(r.meta["lands_with"]))
        lines.append("| " + " | ".join(cells) + " |\n")
    return marker("docs/standards_backlog/") + header + BACKLOG_HEAD + "".join(lines)


def headers_of(files: Mapping[str, str]) -> dict[str, str]:
    """Each family directory's ``_header.md``, by directory: ``docs/lessons/``, or a log's,
    ``docs/design/decisions/world_model/``."""
    out = {}
    for rel, text in files.items():
        if PurePosixPath(rel).name != HEADER:
            continue
        directory = str(PurePosixPath(rel).parent) + "/"
        if any(directory == f.root or (f.per_log and PurePosixPath(directory).parent.as_posix() + "/" == f.root)
               for f in BY_NAME.values()):  # fmt: skip
            out[directory] = text
    return out


def generate(records: list[Record], headers: Mapping[str, str]) -> tuple[dict[str, str], list[str]]:
    """Every generated file, by path, and a finding for each family that has records but no ``_header.md``."""
    by_family: dict[str, list[Record]] = defaultdict(list)
    for record in records:
        by_family[record.family].append(record)
    out: dict[str, str] = {}
    problems: list[str] = []
    singles = (
        ("lessons", LESSONS_FILE, lessons_file),
        ("gaps", GAPS_FILE, gaps_file),
        ("backlog", BACKLOG_FILE, backlog_file),
    )
    for family, path, render in singles:
        root = BY_NAME[family].root
        if root in headers:
            out[path] = render(headers[root], by_family[family])
        elif by_family[family]:
            problems.append(f"{root} holds records but no {HEADER}, so {path} can't be generated (records_layout §3)")
    out |= _decision_files(by_family["decisions"], headers, problems)
    return {path: seal(text) for path, text in out.items()}, problems


def _decision_files(decisions: list[Record], headers: Mapping[str, str], problems: list[str]) -> dict[str, str]:
    root = BY_NAME["decisions"].root
    logs = sorted({d[len(root) :].rstrip("/") for d in headers if d.startswith(root) and d != root})
    relations = Relations.of(decisions)
    out = {f"{root}{log}.md": decision_log(log, headers[f"{root}{log}/"], decisions, relations) for log in logs}
    missing = sorted({log for r in decisions for log in logs_of(r)} - set(logs))
    problems += [f"{root}{log}/ is a decision's log but has no {HEADER} (records_layout §3)" for log in missing]
    if decisions or logs:
        out[DECISIONS_INDEX] = decisions_index(decisions, relations)
    return out


def generation(files: Mapping[str, str]) -> dict[str, str]:
    """What the records and headers among ``files`` generate (a commit's files, say), by path."""
    return generate(load_records(files)[0], headers_of(files))[0]


_CONFLICT = re.compile(r"^(?:<{7}|={7}|>{7}|\|{7})(?: |$)")


def stray_lines(path: str, text: str, generations: Iterable[Mapping[str, str]]) -> list[str]:
    """The lines of a generated file that none of ``generations`` (each a path-to-text map of what some set of
    records generates) produces: text a hand edit added or changed (§6, "regeneration never discards text").

    Line by line, so an edit inside an existing entry (a lesson's body, a row's cell, the head) counts as much as a
    new entry. Conflict markers are not text; a conflict's sides, and a diff3 base, come from the generations of the
    commits being merged. A line that only went missing is not stray: regenerating restores it."""
    allowed: set[str] = set()
    for generation in generations:
        allowed |= set(generation.get(path, "").split("\n"))
    return [line for line in text.split("\n") if line not in allowed and not _CONFLICT.match(line)]


def edit_found(path: str, text: str, known: Iterable[Mapping[str, str]], *, merging: bool) -> str | None:
    """How a generated file was edited other than by ``index``, or None when regenerating it discards nothing.

    A file whose body matches its seal is untouched since ``index`` wrote it (the authoring loop, a stale file after
    a committed record change). Outside a merge, any other body is an edit, a removed or moved line included (delta
    D1, D2). During a merge, or with conflict markers in it, the file is two sealed generations combined, so only a
    line none of the ``known`` generations produces is an edit (``stray_lines``)."""
    if unedited(text):
        return None
    stray = stray_lines(path, text, known)
    if stray:
        return f"holds {stray[0]!r}, which no record generates"
    if merging or any(_CONFLICT.match(line) for line in text.split("\n")):
        return None
    return "was edited since `index` wrote it (its body no longer matches its seal): a line was removed or moved"
